"""Chapter 4 (part C): 4.7 comparison with standards and literature, 4.8 screening LCA and cost, 4.9 integrated assessment, 4.10 limitations."""
from ch4_common import *

TEST = ["NA", "RA", "Rab5", "Rab10", "Rab15", "RCA0", "RCA5", "RCA10", "RCA15"]
NM = {"NA": "NA", "RA": "RA", "Rab5": "Rab5%", "Rab10": "Rab10%", "Rab15": "Rab15%", "RCA0": "RCA 0%", "RCA5": "RCA 5%", "RCA10": "RCA 10%", "RCA15": "RCA 15%",
      "Rab20": "Rab20%*", "Rab25": "Rab25%*"}


def ph(x):
    return f"<ph>{x}</ph>"


def build(b, N):
    res = N["lca"]; inv = N["inv"]; mc = N["mc"]; pr = N["pr"]; tor = N["tor"]; cost = N["cost"]
    S28 = S[S.age == 28].set_index("mix")

    # ------------------------------------------------------------------ 4.7
    b.h2("4.7 การเปรียบเทียบกับเกณฑ์มาตรฐานและงานวิจัยอื่น")
    b.h3("4.7.1 เทียบกับเกณฑ์กำลังอัดของมาตรฐานต่าง ๆ")
    b.p("{fig:rstd} วางค่าเฉลี่ยกำลังอัดที่ 28 วันของทุกสูตรเทียบกับเกณฑ์ขั้นต่ำของมาตรฐานที่รวบรวมไว้ใน{tab:std} เกณฑ์ที่นำมาวาดคือ JIEPA 20 MPa {c:jiepa2017} IS 15658 สำหรับงานไม่มีจราจร 30 MPa {c:is15658} มอก. 827-2565 35 MPa {c:tis827} มอก. 2035-2565 50 MPa {c:tis2035} และ ASTM C936 55 MPa {c:astmc936} ตัวเลขทุกตัวยกมาจากร่างเดิมและยังต้องตรวจกับฉบับจริงของมาตรฐาน")
    b.fig("rstd", fp("r_standards"), 14.0, "กำลังอัดที่ 28 วันของทุกสูตรเทียบกับเกณฑ์ขั้นต่ำของมาตรฐานที่เกี่ยวข้อง แถบคือ ±1 SD ผู้วิจัยสร้างภาพจาก{tab:rfc1} {tab:rfc2} และ{tab:std}")
    n55 = [m for m in TEST if N[f"fc28_{m}"] >= 55]; n50 = [m for m in TEST if N[f"fc28_{m}"] >= 50]
    b.p(f"จำนวนสูตรที่ผ่านแต่ละเกณฑ์ในระดับค่าเฉลี่ยเป็นดังนี้ ผ่านเกณฑ์ 35 MPa {len([m for m in TEST if N['fc28_'+m] >= 35])} จาก 9 สูตร ผ่านเกณฑ์ 50 MPa {len(n50)} สูตร ({', '.join(NM[m] for m in n50)}) และผ่านเกณฑ์ 55 MPa {len(n55)} สูตร ({', '.join(NM[m] for m in n55)}) สูตร Rab10% และ Rab15% ผ่านเฉพาะเกณฑ์ของ มอก. 827-2565 IS 15658 และ JIEPA ซึ่งเป็นเกณฑ์ที่เหมาะกับทางเท้าและพื้นที่จราจรเบา สูตรที่ต้องการให้ใช้ในงานหนักตามเกณฑ์ของ มอก. 2035-2565 ควรจำกัดการลดซีเมนต์ไม่เกินร้อยละ 5")
    b.h3("4.7.2 เทียบกับงานวิจัยอื่นที่ตรวจสอบแล้ว")
    b.p("การเปรียบเทียบกับงานอื่นทำเฉพาะงานที่ผู้วิจัยตรวจสอบการมีอยู่ได้ และใช้เฉพาะข้อความที่ปรากฏในบทคัดย่อหรือข้อมูลสาธารณะของงานนั้น ตัวเลขระดับการทดแทนของแต่ละงานนิยามไม่เหมือนกัน (บางงานเป็นร้อยละของมวลซีเมนต์ บางงานเป็นร้อยละของส่วนผสมทั้งหมด) และวัสดุทดสอบต่างกัน (มอร์ตาร์ คอนกรีตหล่อ บล็อกปูพื้น) จึงเทียบได้เฉพาะทิศทางของผล ไม่ใช่ขนาด")
    b.fig("rlitbc", fp("r_lit_biochar"), 15.0, "ช่วงปริมาณไบโอชาร์ที่งานอื่นทดสอบและทิศทางของผลต่อกำลังอัด เทียบกับชุดที่ 1 ของงานนี้ (ปริมาณไบโอชาร์เป็นร้อยละของมวลซีเมนต์สูตรควบคุม) สีเขียว = กำลังดีขึ้น สีน้ำตาล = กำลังลดลง ผู้วิจัยรวบรวมจากข้อความที่ตรวจสอบแล้วใน{tab:sys}")
    b.p("{fig:rlitbc} แสดงว่างานที่รายงานกำลังดีขึ้นส่วนใหญ่ใช้ไบโอชาร์ในปริมาณน้อย ราวร้อยละ 1 ถึง 9 ของมวลซีเมนต์ ({c:wang2020,gupta2019,suarez2020,ling2023,sacdalan2023,legan2025,chin2025}) งานที่ทดสอบปริมาณสูงกว่ารายงานกำลังลดลง ({c:wang2020,legan2025}) และ Abbas และ Thapa (2025) {c:abbas2025} ที่ทดสอบไบโอชาร์ถึงร้อยละ 60 สรุปว่าเหมาะกับงานไม่รับน้ำหนักเช่นบล็อก ชุดที่ 1 ของงานนี้ใช้ไบโอชาร์ร้อยละ 7.5 15 และ 22.5 ของมวลซีเมนต์ ซึ่งอยู่ในช่วงที่ปริมาณสูงกว่างานส่วนใหญ่ ผลที่กำลังลดลงจึงสอดคล้องกับทิศทางที่งานอื่นพบในช่วงปริมาณนี้ ส่วนที่ต่างจากงานของ Hylton และคณะ (2024) {c:hylton2024} ซึ่งรายงานว่าการทดแทนร้อยละ 10 ของมวลซีเมนต์ไม่ลดกำลังปลายทางเมื่อเลือกไบโอชาร์ตามสมบัติ ผู้วิจัยเห็นว่าสาเหตุที่เป็นไปได้คือ ไบโอชาร์ในงานนี้ยังไม่ได้วัดสมบัติหลัก (ขนาดอนุภาค ความหนาแน่น การดูดซับน้ำ ปริมาณซิลิกอนที่ละลายได้ " + PH + ") ส่วนผสมเป็นแบบอัดแน่นความชื้นต่ำที่ไวต่อการดูดน้ำของไบโอชาร์ และไม่ได้ใช้การกระตุ้นสารเคมีหรือการบ่มด้วย CO<sub>2</sub> เช่นในงานของ Sacdalan และคณะ {c:sacdalan2023} และ Chin และคณะ {c:chin2025} (ข้อความส่วนนี้เป็นข้อสันนิษฐานของผู้วิจัย)")
    b.fig("rlitrca", fp("r_lit_rca"), 14.0, "ช่วงการแทนที่มวลรวมด้วย RCA ที่งานอื่นทดสอบ เทียบกับงานนี้ (ร้อยละตามนิยามของแต่ละงาน) ผู้วิจัยรวบรวมจากข้อความที่ตรวจสอบแล้วใน{tab:sys}")
    dra = abs(pct(N["fc28_RA"], N["fc28_NA"]))
    b.p(f"สำหรับ RCA {{fig:rlitrca}} แสดงว่างานนี้ใช้ในช่วงที่งานอื่นทดสอบเช่นกัน Contreras Llanes และคณะ (2022) {{c:contreras2022}} ทดสอบการแทนที่มวลรวมด้วย C&DW ถึงร้อยละ 50 ในงานปูพื้น และพบว่าการดูดซึมน้ำและกำลังดึงใกล้เคียงสูตรอ้างอิง Rodríguez และคณะ (2017) {{c:rodriguez2017}} รายงานว่าบล็อกที่ใช้ RCA ร้อยละ 15 และ 30 ผ่านข้อกำหนด EN 1338 แต่กำลังและความหนาแน่นลดลงเมื่อสัดส่วน RCA เพิ่ม Namarak และคณะ (2018) {{c:namarak2018}} ผลิตบล็อกจาก RCA ร้อยละ 100 กับวัสดุประสานที่ไม่ใช่ซีเมนต์ปอร์ตแลนด์และผ่านเกณฑ์ มอก. 827 ผลของงานนี้ที่เปลี่ยนจาก NA เป็น RA ลดกำลัง {dra:.0f} % สอดคล้องกับงานที่รายงานกำลังลดตามสัดส่วน RCA {{c:wangx2019,rodriguez2017}} ขณะที่ผลของชุดที่ 2 ซึ่งกำลังเพิ่มตาม RCA ขัดกับแนวโน้มนี้ จึงเป็นประเด็นที่ต้องยืนยันซ้ำ (หัวข้อ 4.3.2)")
    rows = [
        ["ไบโอชาร์ทดแทนซีเมนต์ ปริมาณต่ำ (ประมาณร้อยละ 5)", f"Rab5%: กำลัง 28 วันลด {abs(pct(N['fc28_Rab5'], N['fc28_RA'])):.0f} % เทียบ RA (ไม่มีนัยสำคัญ n = 3)", "Legan 2025 {c:legan2025}: ไบโอชาร์ไม้ 5 10 15 % ในมอร์ตาร์ มีเฉพาะ 5 % ที่เกินสูตรควบคุมที่ 7 และ 28 วัน Hylton 2024 {c:hylton2024}: ทดแทน 10 % ไม่ลดกำลังปลายทางเมื่อเลือกไบโอชาร์ตามสมบัติ", "ทิศทางต่างกันบางส่วน"],
        ["ไบโอชาร์ปริมาณสูง (≥ 10 %)", f"Rab10%, Rab15%: ลด {abs(pct(N['fc28_Rab10'], N['fc28_RA'])):.0f} % และ {abs(pct(N['fc28_Rab15'], N['fc28_RA'])):.0f} %", "Wang 2020 {c:wang2020}: ปริมาณสูงลดกำลังเพราะโครงสร้างพรุนและเปราะ Abbas 2025 {c:abbas2025}: ทดสอบ 5–60 % เหมาะกับงานไม่รับน้ำหนัก", "สอดคล้อง"],
        ["ไบโอชาร์จากไผ่", "ไม่กระตุ้น ไม่บ่มด้วย CO<sub>2</sub> สมบัติไบโอชาร์ยังไม่วัด " + PH, "Sacdalan 2023 {c:sacdalan2023}: ทดแทนซีเมนต์ 2 5 8 % ด้วยไบโอชาร์ไผ่ที่กระตุ้นด้วย NaOH กำลัง 28 วันสูงกว่าสูตรควบคุม Chin 2025 {c:chin2025}: ดีที่สุดที่ 6 % w/c 0.45 และการบ่มด้วย CO<sub>2</sub> เพิ่มกำลัง", "เทียบตรงไม่ได้ (เงื่อนไขต่างกัน)"],
        ["RCA ต่อกำลังของบล็อก", f"ชุดที่ 1: เปลี่ยนจาก NA เป็น RA ลด {abs(pct(N['fc28_RA'], N['fc28_NA'])):.0f} % ชุดที่ 2: RCA 0→15 % เพิ่ม {pct(N['fc28_RCA15'], N['fc28_RCA0']):.0f} %", "Wang 2019 {c:wangx2019} และ Rodríguez 2017 {c:rodriguez2017}: RCA ลดกำลังและเพิ่มการดูดซึมน้ำ Poon 2006 {c:poon2006}: ผสมอิฐบดกับ RCA ลดกำลัง", "ชุดที่ 1 สอดคล้อง ชุดที่ 2 ไม่สอดคล้อง"],
        ["ระดับ RCA ที่ใช้ได้", "ชุดที่ 1 ใช้ RCA 50 % ของมวลรวมละเอียด ผ่านเกณฑ์ 35 MPa ทุกสูตร", "Contreras 2022 {c:contreras2022}: ถึง 50 % ได้ผลใกล้เคียงสูตรอ้างอิง Rodríguez 2017 {c:rodriguez2017}: 15 และ 30 % ผ่าน EN 1338", "สอดคล้อง"],
        ["การดูดซึมน้ำ", f"{a_min(N):.2f}–{a_max(N):.2f} % (ทุกค่าต่ำกว่า 5 %)", "Wang 2019 {c:wangx2019}: RCA เพิ่มการดูดซึมน้ำของบล็อก", "ยังเห็นไม่ชัดในช่วง RCA ≤ 15 % (ค่าผิดปกติรอยืนยัน)"],
        ["กำลังของบล็อก RCA เทียบเกณฑ์ไทย", f"{f1(N['fc28_Rab15'])}–{f1(N['fc28_RCA15'])} MPa (ทุกสูตรเกิน 35 MPa)", "Namarak 2018 {c:namarak2018}: RCA 100 % กับวัสดุประสานไม่ใช้ปอร์ตแลนด์ ผ่าน มอก. 827", "สอดคล้อง (คนละวัสดุประสาน)"],
        ["ซีเมนต์เป็นตัวกำหนด GWP", f"ซีเมนต์คิดเป็น {N['share_min']:.1f}–{N['share_max']:.1f} % ของ GWP", "Pizoń 2026 {c:pizon2026}: ซีเมนต์เป็นตัวกำหนด GWP ของคอนกรีตที่ใช้มวลรวมจากบล็อกบด Knoeri 2013 {c:knoeri2013}: GWP ขึ้นกับปริมาณซีเมนต์ที่เพิ่ม", "สอดคล้อง"],
        ["ไบโอชาร์ต่อ GWP", f"กรณี A: −{abs(N['lca'].loc['Rab5','gwp_A_vs_ctrl_pct']):.1f} % ที่ Rab5% กรณี B: {pct(N['gwpB_Rab5'], N['gwpB_RA']):.0f} %", "Wang D 2026 {c:wangd2026}: ไบโอชาร์ทดแทนซีเมนต์/ทรายให้ GWP ติดลบเมื่อนับพลังงานร่วมและการกักเก็บ Ambaye 2026 {c:ambaye2026}: 5 % ลดผลกระทบที่ต้นทุนใกล้เคียง", "ทิศทางสอดคล้อง ขนาดขึ้นกับเครดิต"],
    ]
    b.table("rlit", "การเปรียบเทียบผลของงานนี้กับงานวิจัยอื่นที่ตรวจสอบแล้ว", ["ประเด็น", "งานนี้", "งานอื่นที่ตรวจสอบแล้ว", "ความสอดคล้อง"], rows, [1650, 2150, 3900, 1400], align=["left"] * 4, sz=18,
            note="หมายเหตุ ข้อความของงานอื่นยกจากข้อมูลบทคัดย่อ/หน้าสำนักพิมพ์ที่ตรวจพบ ไม่ได้อ่านฉบับเต็มทุกงาน การเทียบทำเพื่อดูทิศทาง ไม่ใช่ขนาดของผล")

    # ------------------------------------------------------------------ 4.8
    b.h2("4.8 ผลการประเมินคาร์บอนเบื้องต้นและต้นทุนวัสดุ")
    b.p("หัวข้อนี้นำเสนอผลการประเมินวัฏจักรชีวิตเบื้องต้นแบบ cradle-to-gate ตามวิธีในหัวข้อ 3.7 หน่วยหน้าที่คือบล็อกคอนกรีต 1 ลูกบาศก์เมตร ผลเป็นค่าคำนวณจากปริมาณวัสดุของแต่ละสูตรและตัวประกอบการปล่อยที่ผู้วิจัยกำหนดใน{tab:ef} ซึ่งหลายตัวเป็นค่าสมมติ " + PH + " ผลจึงใช้เปรียบเทียบสูตรกันเอง ไม่ใช่ค่าสิ่งแวดล้อมของผลิตภัณฑ์ที่ยืนยันแล้ว")
    b.h3("4.8.1 ปริมาณวัสดุต่อหนึ่งลูกบาศก์เมตร")
    rows = []
    for m in TEST + ["Rab20", "Rab25"]:
        r = inv.loc[m]; rows.append([NM[m], f"{r.cement:.1f}", f"{r.sand:.1f}", f"{r.stone:.1f}", f"{r.rca:.1f}", f"{r.biochar:.1f}", f"{r.cement + r.sand + r.stone + r.rca + r.biochar:,.0f}"])
    b.table("rinv", "ปริมาณวัสดุต่อบล็อก 1 ลูกบาศก์เมตร (กก./ม.³)", ["สูตร", "ซีเมนต์", "ทราย", "หิน", "RCA", "ไบโอชาร์", "รวม"], rows, [1700, 1200, 1200, 1200, 1200, 1300, 1200], sz=20,
            note="หมายเหตุ คำนวณจากมวลวัสดุแห้งต่อก้อนในตาราง {tab:mix} หารด้วยปริมาตรก้อน 0.00156 ลบ.ม. * สูตรที่ออกแบบแต่ยังไม่มีผลทดสอบกำลังอัด จึงแสดงเฉพาะ GWP ผลรวมไม่ใช่ความหนาแน่นจริงของบล็อก (ไม่รวมน้ำ)")
    b.h3("4.8.2 ศักยภาพการทำให้โลกร้อน (GWP)")
    rows = []
    for m in TEST:
        r = res.loc[m]
        rows.append([NM[m], f"{r.fc28:.1f}", f"{r.gwp_A:.1f}", "—" if m in ("NA", "RA", "RCA0") else f"{r.gwp_A_vs_ctrl_pct:+.1f}", f"{r.gwp_B:.1f}", f"{r.gwpA_cement / r.gwp_A * 100:.1f}", f"{r.gwpA_per_MPa:.2f}", f"{r.gwpB_per_MPa:.2f}"])
