def mcv(mc, scen, mix, col):
    return float(mc[(mc.scenario == scen) & (mc["mix"] == mix)][col].iloc[0])


def prv(pr, scen, mix):
    return float(pr[(pr.scenario == scen) & (pr["mix"] == mix)].p_lower.iloc[0])


def costv(cost, mix, r, col):
    return float(cost[(cost["mix"] == mix) & (cost.r == r)][col].iloc[0])


def a_min(N):
    return float(min(pd.read_csv(os.path.join(DATA, "absorption_series2.csv"))[["s1", "s2", "s3"]].min().min(), pd.read_csv(os.path.join(DATA, "absorption_series1_rab5.csv")).abs_pct.min()))


def a_max(N):
    return float(max(pd.read_csv(os.path.join(DATA, "absorption_series2.csv"))[["s1", "s2", "s3"]].max().max(), pd.read_csv(os.path.join(DATA, "absorption_series1_rab5.csv")).abs_pct.max()))
